1	import { randomUUID } from "node:crypto";
2	
3	import { clearSmokeGraphThread } from "@/lib/agent/smoke-checkpointer";
4	import { smokeGraph, smokeGraphInput } from "@/lib/agent/smoke-graph";
5	import { isSmokeEndpointEnabled } from "@/lib/agent/smoke-access";
6	import { createNeatlogsHandler, flushNeatlogs } from "@/lib/neatlogs";
7	
8	export const runtime = "nodejs";
9	
10	const encoder = new TextEncoder();
11	
12	function sse(event: string, data: unknown) {
13	  return encoder.encode(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
14	}
15	
16	export async function POST(request: Request) {
17	  if (!isSmokeEndpointEnabled(process.env)) {
18	    return new Response("Not found", { status: 404 });
19	  }
20	
21	  const runId = randomUUID();
22	  const graphAbort = new AbortController();
23	  let cancelled = false;
24	  const abortGraph = () => graphAbort.abort(request.signal.reason);
25	  request.signal.addEventListener("abort", abortGraph, { once: true });
26	
27	  const body = await request.json().catch(() => ({}));
28	  const domain =
29	    typeof body === "object" &&
30	    body !== null &&
31	    "domain" in body &&
32	    typeof body.domain === "string"
33	      ? body.domain
34	      : "example.com";
35	
36	  const stream = new ReadableStream<Uint8Array>({
37	    async start(controller) {
38	      try {
39	        const handler = await createNeatlogsHandler();
40	        controller.enqueue(sse("run", { runId }));
41	
42	        const events = await smokeGraph.stream(smokeGraphInput(domain), {
43	          configurable: { thread_id: runId },
44	          streamMode: ["updates", "messages"],
45	          callbacks: [handler],
46	          tags: ["variant:smoke"],
47	          runId,
48	          signal: graphAbort.signal,
49	        });
50	
51	        for await (const event of events) {
52	          controller.enqueue(sse("graph", event));
53	        }
54	
55	        controller.enqueue(sse("done", { runId }));
56	      } catch (error) {
57	        if (!graphAbort.signal.aborted) {
58	          controller.enqueue(
59	            sse("error", {
60	              runId,
61	              message: error instanceof Error ? error.message : "Unknown error",
62	            }),
63	          );
64	        }
65	      } finally {
66	        request.signal.removeEventListener("abort", abortGraph);
67	        await Promise.all([
68	          clearSmokeGraphThread(runId),
69	          flushNeatlogs().catch(() => false),
70	        ]);
71	        if (!cancelled) {
72	          controller.close();
73	        }
74	      }
75	    },
76	    cancel(reason) {
77	      cancelled = true;
78	      graphAbort.abort(reason);
79	    },
80	  });
81	
82	  return new Response(stream, {
83	    headers: {
84	      "Cache-Control": "no-cache, no-transform",
85	      Connection: "keep-alive",
86	      "Content-Type": "text/event-stream; charset=utf-8",
87	    },
88	  });
89	}
